-- State transitions declared for SubscriptionBillingRun (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION subscription.subscription_billing_runs_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('failed', 'pending'), ('pending', 'failed'), ('pending', 'invoiced'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: subscription_billing_runs.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS subscription_billing_runs_status_transition_check ON subscription.subscription_billing_runs;
CREATE TRIGGER subscription_billing_runs_status_transition_check
    BEFORE UPDATE OF "status" ON subscription.subscription_billing_runs
    FOR EACH ROW EXECUTE FUNCTION subscription.subscription_billing_runs_status_transition_check();
